css:
.powerofyes-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1a2233;
    background: linear-gradient(160deg, #f4f1ea 0%, #ece6da 100%);
    border-radius: 18px;
}

.powerofyes-container * {
    box-sizing: border-box;
}

.powerofyes-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0a1733 0%, #14264f 55%, #1f3a6e 100%);
    color: #f5f2ea;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 12px 34px rgba(10, 23, 51, 0.34);
    border-bottom: 3px solid #c9a227;
}

.powerofyes-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #f8f4e8;
}

.powerofyes-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.3px;
    font-weight: 700;
    color: #e7cf7f;
    background: rgba(201, 162, 39, 0.16);
    padding: 5px 14px;
    border-radius: 999px;
}

.powerofyes-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.58;
    color: #d7ddea;
}

.powerofyes-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #2c3a57;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.powerofyes-period-counter #currentDay,
.powerofyes-period-counter #maxPeriods {
    font-weight: 800;
    color: #0a1733;
}

.powerofyes-round-name {
    background: #e6dcc0;
    color: #5a4410;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.powerofyes-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a2c1a;
    background: #f4ddd5;
    padding: 4px 12px;
    border-radius: 999px;
}

.powerofyes-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.powerofyes-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0d8c6;
    box-shadow: 0 4px 14px rgba(10, 23, 51, 0.07);
    border-top: 4px solid #1f3a6e;
}

.powerofyes-card-clarity { border-top-color: #1f3a6e; }
.powerofyes-card-position { border-top-color: #0b6e57; }
.powerofyes-card-mandate { border-top-color: #6a4fb0; }
.powerofyes-card-capital { border-top-color: #c9a227; }

.powerofyes-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b6555;
}

.powerofyes-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0a1733;
}

.powerofyes-card-clarity .powerofyes-value { color: #1f3a6e; }
.powerofyes-card-position .powerofyes-value { color: #0b6e57; }
.powerofyes-card-mandate .powerofyes-value { color: #6a4fb0; }
.powerofyes-card-capital .powerofyes-value { color: #a6841c; font-size: 1.7rem; }

.powerofyes-sublabel {
    font-size: 0.76rem;
    color: #7a7464;
    line-height: 1.35;
}

.powerofyes-card-capital-over { border-top-color: #c0392b; }
.powerofyes-card-capital-over .powerofyes-value { color: #c0392b; }

.powerofyes-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 8px;
    background: #0a1733;
    color: #eef2f8;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 4px solid #c9a227;
}

.powerofyes-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #e7cf7f;
}

.powerofyes-covenant {
    font-size: 0.82rem;
    font-weight: 700;
    background: rgba(11, 110, 87, 0.28);
    color: #a9e6d2;
    padding: 4px 12px;
    border-radius: 999px;
}

.powerofyes-covenant.powerofyes-covenant-breach {
    background: rgba(192, 57, 43, 0.28);
    color: #f3b4ac;
}

.powerofyes-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c9a227;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(10, 23, 51, 0.06);
}

.powerofyes-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.powerofyes-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0a1733;
    margin-bottom: 6px;
}

.powerofyes-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #2c3850;
}

.powerofyes-briefing-text strong { color: #1f3a6e; }
.powerofyes-briefing-text em { color: #8a2c1a; font-style: italic; }

.powerofyes-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0d8c6;
    box-shadow: 0 4px 14px rgba(10, 23, 51, 0.07);
}

.powerofyes-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0a1733;
    border-bottom: 2px solid #ece6da;
    padding-bottom: 8px;
}

.powerofyes-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #243150;
    margin: 14px 0 6px;
}

.powerofyes-container select,
.powerofyes-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #cdbf9e;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdfbf6;
    color: #1a2233;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.powerofyes-container select:focus,
.powerofyes-container input[type="number"]:focus {
    outline: none;
    border-color: #c9a227;
    box-shadow: 0 0 0 3px rgba(201, 162, 39, 0.18);
}

.powerofyes-container select option {
    background-color: #ffffff;
    color: #1a2233;
}

.powerofyes-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c9a227;
}

.powerofyes-range-readout,
.powerofyes-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #243150;
    margin-top: 4px;
}

.powerofyes-range-readout span:last-child,
.powerofyes-alloc-readout span:nth-child(2) {
    color: #a6841c;
    font-weight: 800;
}

.powerofyes-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.powerofyes-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f7f3ea;
    border: 1px solid #e6dcc6;
    border-radius: 9px;
    padding: 8px 12px;
}

.powerofyes-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #243150;
}

.powerofyes-alloc-row input[type="number"] {
    width: 92px;
    flex: 0 0 92px;
}

.powerofyes-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.powerofyes-container .btn-primary {
    background: linear-gradient(135deg, #14264f 0%, #1f3a6e 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    color: #f6f1e3;
    box-shadow: 0 6px 16px rgba(20, 38, 79, 0.30);
    border-bottom: 2px solid #c9a227;
}

.powerofyes-container .btn-primary:hover {
    filter: brightness(1.10);
}

.powerofyes-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #cdbf9e;
    color: #6b6555;
}

.powerofyes-coach {
    background: linear-gradient(135deg, #0a1733 0%, #16284c 100%);
    color: #eef2f8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(10, 23, 51, 0.24);
    border-left: 4px solid #c9a227;
}

.powerofyes-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e7cf7f;
    margin-bottom: 8px;
}

.powerofyes-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.powerofyes-coach-body strong { color: #f0d98a; }
.powerofyes-coach-body em { color: #f3b9aa; font-style: italic; }

.powerofyes-history,
.powerofyes-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0d8c6;
    box-shadow: 0 4px 14px rgba(10, 23, 51, 0.07);
}

.powerofyes-history h3,
.powerofyes-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0a1733;
}

.powerofyes-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #243150;
}

.powerofyes-container table#usfHistoryTable th {
    background: #f1ead9;
    color: #0a1733;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e0d4b4;
}

.powerofyes-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0ece1;
}

.powerofyes-container table#usfHistoryTable tr:nth-child(even) td {
    background: #faf7f0;
}

.powerofyes-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .powerofyes-container {
        padding: 14px;
    }
    .powerofyes-header h1 {
        font-size: 1.7rem;
    }
    .powerofyes-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .powerofyes-value {
        font-size: 2rem;
    }
    .powerofyes-card-capital .powerofyes-value {
        font-size: 1.4rem;
    }
    .powerofyes-clock {
        margin-left: 0;
    }
    .powerofyes-period-counter {
        font-size: 0.88rem;
    }
    .powerofyes-budget-bar {
        flex-direction: column;
        align-items: flex-start;
    }
    .powerofyes-alloc-row {
        flex-wrap: wrap;
    }
    .powerofyes-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .powerofyes-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (powerofyes) ---- */
.powerofyes-completion { padding: 8px 4px 4px; }
.powerofyes-cm-head { text-align: center; margin-bottom: 16px; }
.powerofyes-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #4a5fb0; }
.powerofyes-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #7c8bc9; }
.powerofyes-cm-grade { font-size: 1.15rem; font-weight: 700; margin-top: 6px; color: #262b3a; }
.powerofyes-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.powerofyes-cm-yes { background: rgba(74,95,176,0.16); color: #3a4ea0; border: 1px solid rgba(74,95,176,0.55); }
.powerofyes-cm-no { background: rgba(180,70,55,0.12); color: #a5412c; border: 1px solid rgba(180,70,55,0.45); }
.powerofyes-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.powerofyes-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(74,95,176,0.08); border: 1px solid rgba(74,95,176,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.powerofyes-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #3d51a0; }
.powerofyes-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #656b7c; text-transform: uppercase; letter-spacing: 0.03em; }
.powerofyes-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #262b3a; }
.powerofyes-cm-insights { margin: 0; padding-left: 20px; }
.powerofyes-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #363c4b; }

