(function() {
    'use strict';

    class PowerOfYesAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `The Power of Yes`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card.
            this.ENVELOPE = 220;        // EUR 220M transformation envelope
            this.COVENANT = 2.5;        // 2.5x net-debt/EBITDA covenant
            this.OVERSPREAD = 30;       // a single bet under ~€30M "builds nothing that wins"

            // Starting KPIs (0-100) — deliberately low so every lever has headroom.
            this.START_CLARITY = 12;
            this.START_POSITION = 20;
            this.START_MANDATE = 15;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    clarity: this.START_CLARITY,
                    position: this.START_POSITION,
                    mandate: this.START_MANDATE,
                    capital: 0,
                    overCap: false,
                    covenantBreach: false,
                    diagnosed: false,
                    focusedPair: false,
                    declinedClean: false,
                    realOption: false,
                    clarityHistory: [this.START_CLARITY],
                    positionHistory: [this.START_POSITION],
                    mandateHistory: [this.START_MANDATE],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately MIDDLING — a click-through must not auto-win.
                state.decisions = {
                    question: `value`,      // a partial diagnosis, not the digital-relevance answer
                    fit: `copy`,            // matching rivals, not building durable advantage
                    decisiveness: 50,       // half-committed
                    omni: 55, loyalty: 55, discount: 55, quick: 55,  // the polite four-way spread
                    mode: `full`,           // all-in, no off-ramp
                    decline: `token`,       // a slice in everything, declines nothing
                    first: `parallel`,      // everything at once
                    gates: `reassess`,      // no fixed gates
                    comms: `afterproof`,    // say nothing until sure
                    covenant: 50,
                    prudent: `dilute`,      // compromise into mush
                    metrics: `lagonly`,
                    wrong: `confidence`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const q = document.getElementById(`questionInput`);
                const fit = document.getElementById(`fitInput`);
                const dec = document.getElementById(`decisivenessInput`);
                if (q) decisions.question = q.value;
                if (fit) decisions.fit = fit.value;
                if (dec) decisions.decisiveness = parseInt(dec.value, 10);
                if (!Number.isFinite(decisions.decisiveness) || decisions.decisiveness < 0 || decisions.decisiveness > 100) {
                    warn(`warn_decisiveness_range`); return false;
                }
            } else if (round === 2) {
                const omni = document.getElementById(`omniInput`);
                const loyalty = document.getElementById(`loyaltyInput`);
                const discount = document.getElementById(`discountInput`);
                const quick = document.getElementById(`quickInput`);
                if (omni) decisions.omni = parseFloat(omni.value);
                if (loyalty) decisions.loyalty = parseFloat(loyalty.value);
                if (discount) decisions.discount = parseFloat(discount.value);
                if (quick) decisions.quick = parseFloat(quick.value);
                const parts = [decisions.omni, decisions.loyalty, decisions.discount, decisions.quick];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = decisions.omni + decisions.loyalty + decisions.discount + decisions.quick;
                if (total > this.ENVELOPE) {
                    warn(`warn_alloc_over`); return false;
                }
                const mode = document.getElementById(`modeInput`);
                const decline = document.getElementById(`declineInput`);
                if (mode) decisions.mode = mode.value;
                if (decline) decisions.decline = decline.value;
            } else if (round === 3) {
                const first = document.getElementById(`firstInput`);
                const gates = document.getElementById(`gatesInput`);
                const comms = document.getElementById(`commsInput`);
                const cov = document.getElementById(`covenantInput`);
                if (first) decisions.first = first.value;
                if (gates) decisions.gates = gates.value;
                if (comms) decisions.comms = comms.value;
                if (cov) decisions.covenant = parseInt(cov.value, 10);
                if (!Number.isFinite(decisions.covenant) || decisions.covenant < 0 || decisions.covenant > 100) {
                    warn(`warn_covenant_range`); return false;
                }
            } else if (round === 4) {
                const pr = document.getElementById(`prudentInput`);
                const me = document.getElementById(`metricsInput`);
                const wr = document.getElementById(`wrongInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pr) decisions.prudent = pr.value;
                if (me) decisions.metrics = me.value;
                if (wr) decisions.wrong = wr.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas onto the three 0-100 KPIs.
            let clarityDelta = 0, positionDelta = 0, mandateDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Frame the REAL strategic question (Common Error 3: bold bet, no diagnosis).
                // The concept's answer is a digital-RELEVANCE problem, not value-defence or scale-only.
                if (d.question === `digital`) {
                    clarityDelta += 14; positionDelta += 4; ds.diagnosed = true; coachKey = `coach_r1_digital`;
                } else if (d.question === `value`) {
                    clarityDelta += 5; coachKey = `coach_r1_value`;
                } else if (d.question === `scale`) {
                    clarityDelta += 2; coachKey = `coach_r1_scale`;
                } else { // none — keeping optionality open = the polite maybe
                    clarityDelta -= 8; mandateDelta -= 4; coachKey = `coach_r1_none`;
                }

                // Where €220M builds DURABLE advantage vs merely matching rivals (Porter/Rumelt).
                if (d.fit === `focused`) {
                    clarityDelta += 10; positionDelta += 6;
                    if (d.question === `digital`) coachKey = `coach_r1_sharp`;
                } else if (d.fit === `copy`) {
                    clarityDelta -= 6; positionDelta -= 2; coachKey = `coach_r1_copy`;
                } else if (d.fit === `cheapest`) {
                    clarityDelta -= 8; positionDelta -= 4; coachKey = `coach_r1_cheapest`;
                } else { // defer — the data isn't clear enough
                    clarityDelta -= 10; mandateDelta -= 4; coachKey = `coach_r1_defer`;
                }

                // Decisiveness: willingness to commit a yes inside 100 days (decision speed).
                if (d.decisiveness >= 70) { clarityDelta += 6; mandateDelta += 4; }
                else if (d.decisiveness <= 30) { clarityDelta -= 8; mandateDelta -= 4; coachKey = `coach_r1_hedge`; }

                summaryKey = (d.question === `digital` && d.fit === `focused`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Commit the bet — allocate under the cap (Common Errors 1 & 4).
                const alloc = { omni: d.omni, loyalty: d.loyalty, discount: d.discount, quick: d.quick };
                ds.capital = d.omni + d.loyalty + d.discount + d.quick;
                ds.overCap = ds.capital > this.ENVELOPE;

                // Count "funded" bets (a bet under ~€30M builds nothing that wins).
                const funded = Object.values(alloc).filter((v) => v >= this.OVERSPREAD).length;
                // Identify the lead/relevance bet (omni) and the margin/data engine (loyalty).
                const relevanceFunded = alloc.omni >= 90;          // a real omnichannel rebuild needs scale
                const engineFunded = alloc.loyalty >= this.OVERSPREAD;
                const focusedPair = funded === 2 && relevanceFunded && engineFunded;
                ds.focusedPair = focusedPair;

                if (focusedPair) {
                    // The concept-correct play: a focused pair that compounds — relevance + data/margin engine.
                    clarityDelta += 12; positionDelta += 16; coachKey = `coach_r2_focused`;
                } else if (funded >= 4 || (funded === 0)) {
                    // Spread thinly across all four = four polite maybes (Decision Tree #1).
                    clarityDelta -= 12; positionDelta -= 8; mandateDelta -= 4; coachKey = `coach_r2_spread`;
                } else if (funded === 3) {
                    clarityDelta -= 4; positionDelta += 2; coachKey = `coach_r2_three`;
                } else if (funded === 2 && !relevanceFunded) {
                    // Two bets, but no real relevance engine — defended the value floor, ceded the future.
                    clarityDelta += 4; positionDelta += 4; coachKey = `coach_r2_norelevance`;
                } else {
                    clarityDelta += 6; positionDelta += 6;
                }
                // Reward staying inside the envelope; penalise blowing the cap.
                if (ds.overCap) { mandateDelta -= 10; positionDelta -= 6; coachKey = `coach_r2_overcap`; }

                // Commitment mode — operationalising the "yes" (Real Options & Staged Commitment).
                if (d.mode === `staged`) {
                    clarityDelta += 8; positionDelta += 6; ds.realOption = true;
                    if (focusedPair) coachKey = `coach_r2_staged`;
                } else if (d.mode === `full`) {
                    // All-in, no off-ramp: decisive but unbounded downside (covenant/write-down risk).
                    clarityDelta += 4; positionDelta += 2; mandateDelta -= 8;
                } else if (d.mode === `partner`) {
                    positionDelta -= 2; coachKey = `coach_r2_partner`;
                } else { // pilot — tiny, reassess in 12 months: disguised maybe (Common Error 4)
                    clarityDelta -= 10; positionDelta -= 6; coachKey = `coach_r2_pilot`;
                }

                // Strategy is what you choose NOT to do (Rumelt).
                if (d.decline === `explicit`) {
                    clarityDelta += 10; mandateDelta += 6; ds.declinedClean = true;
                } else if (d.decline === `token`) {
                    clarityDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r2_token` : coachKey;
                } else { // silent
                    clarityDelta -= 4; mandateDelta -= 4;
                }

                summaryKey = (focusedPair && !ds.overCap && d.mode === `staged` && d.decline === `explicit`) ? `sum_r2_good` :
                             (funded >= 4 || funded === 0) ? `sum_r2_spread` : `sum_r2_weak`;
            } else if (round === 3) {
                // Sequence the moves (Common Error 4: real options as a fig leaf).
                // Lower-capital enabler first banks an early proof point that funds/de-risks the bold bet.
                if (d.first === `enabler`) {
                    positionDelta += 12; clarityDelta += 6; coachKey = `coach_r3_enabler`;
                } else if (d.first === `boldfirst`) {
                    positionDelta -= 2; coachKey = `coach_r3_boldfirst`;
                } else { // parallel — both at once burns cash and capacity at once
                    positionDelta -= 8; mandateDelta -= 4; coachKey = `coach_r3_parallel`;
                }

                // Gating: a scale trigger AND kill-criteria = a real staged commitment.
                if (d.gates === `bothgates`) {
                    clarityDelta += 8; positionDelta += 8; mandateDelta += 6; ds.realOption = true;
                    if (d.first === `enabler`) coachKey = `coach_r3_disciplined`;
                } else if (d.gates === `triggeronly`) {
                    clarityDelta += 2; positionDelta -= 4; coachKey = `coach_r3_trigger`;
                } else { // reassess — no fixed gates = the maybe in a real-options costume
                    clarityDelta -= 10; positionDelta -= 6; coachKey = `coach_r3_reassess`;
                }

                // Communicate the direction now vs hide (Stakeholder Alignment).
                if (d.comms === `commitnow`) {
                    mandateDelta += 12; clarityDelta += 4;
                } else if (d.comms === `afterproof`) {
                    mandateDelta -= 6; coachKey = (coachKey === `coach_default`) ? `coach_r3_afterproof` : coachKey;
                } else { // hedge — a broad "exploring options" review keeps everyone comfortably uncommitted
                    clarityDelta -= 6; mandateDelta -= 8; coachKey = `coach_r3_hedge`;
                }

                // Covenant discipline: keep headroom under the 2.5x test before drawing the next tranche.
                if (d.covenant >= 60) { positionDelta += 6; mandateDelta += 4; ds.covenantBreach = false; }
                else if (d.covenant <= 25) { positionDelta -= 8; mandateDelta -= 6; ds.covenantBreach = true; coachKey = `coach_r3_covenant`; }

                summaryKey = (d.first === `enabler` && d.gates === `bothgates` && d.comms === `commitnow`) ? `sum_r3_good` :
                             (d.gates === `reassess`) ? `sum_r3_figleaf` : `sum_r3_weak`;
            } else if (round === 4) {
                // Defend the yes to a split board (Common Error 5: direction without alignment).
                if (d.prudent === `givecertainty`) {
                    // Convert dissent into a mandate WITHOUT diluting the bet.
                    mandateDelta += 22; clarityDelta += 4; coachKey = `coach_r4_certainty`;
                } else if (d.prudent === `steamroll`) {
                    // Two votes + the Chair's mandate, but the prudent faction and 35% block brief against you.
                    mandateDelta -= 14; positionDelta -= 4; coachKey = `coach_r4_steamroll`;
                } else { // dilute — a compromise that builds nothing that wins
                    clarityDelta -= 12; positionDelta -= 8; mandateDelta += 2; coachKey = `coach_r4_dilute`;
                }

                // Accountability metrics you put your own neck behind.
                if (d.metrics === `leadlag`) {
                    clarityDelta += 10; mandateDelta += 10;
                } else if (d.metrics === `lagonly`) {
                    mandateDelta += 2; coachKey = (coachKey === `coach_default`) ? `coach_r4_lagonly` : coachKey;
                } else { // none — ask the board to trust the vision
                    mandateDelta -= 10; clarityDelta -= 4; coachKey = `coach_r4_nometrics`;
                }

                // "What if you're WRONG about omnichannel?" — a bounded wrong beats being late.
                if (d.wrong === `killcap`) {
                    positionDelta += 12; mandateDelta += 8;
                    if (d.prudent === `givecertainty`) coachKey = `coach_r4_killcap`;
                } else if (d.wrong === `confidence`) {
                    mandateDelta -= 8; coachKey = `coach_r4_confidence`;
                } else { // hedge — "we kept enough spread that no bet can hurt us" recreates the spread-bet
                    clarityDelta -= 8; positionDelta -= 6; coachKey = `coach_r4_hedge`;
                }

                // Conviction nudges the mandate (defend a yes over a comfortable maybe).
                mandateDelta += Math.round((d.conviction - 50) / 8);

                summaryKey = (d.prudent === `givecertainty` && d.metrics === `leadlag` && d.wrong === `killcap`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Apply deltas with floors/ceilings.
            ds.clarity = Math.max(0, Math.min(100, ds.clarity + clarityDelta));
            ds.position = Math.max(0, Math.min(100, ds.position + positionDelta));
            ds.mandate = Math.max(0, Math.min(100, ds.mandate + mandateDelta));

            ds.clarityHistory.push(Math.round(ds.clarity));
            ds.positionHistory.push(Math.round(ds.position));
            ds.mandateHistory.push(Math.round(ds.mandate));

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                clarity: Math.round(ds.clarity),
                clarityDelta: Math.round(clarityDelta),
                position: Math.round(ds.position),
                positionDelta: Math.round(positionDelta),
                mandate: Math.round(ds.mandate),
                mandateDelta: Math.round(mandateDelta),
                capital: Math.round(ds.capital),
                overCap: ds.overCap,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _money(m) {
            // Locale-aware EUR millions. EN: €2.4M (symbol before). ES: 2,4 M€ (symbol after, comma decimal).
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const n = Math.round(Number(m));
            if (lang === `es`) {
                return n.toLocaleString(`es-ES`) + ` M€`;
            }
            return `€` + n.toLocaleString(`en-US`) + `M`;
        }

        setupUI(uiManager) {
            const self = this;
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`clarityDisplay`, `domainState.clarity`, (v) => Math.round(Number(v)));
            uiManager.bind(`positionDisplay`, `domainState.position`, (v) => Math.round(Number(v)));
            uiManager.bind(`mandateDisplay`, `domainState.mandate`, (v) => Math.round(Number(v)));

            const capitalFmt = (v) => {
                const used = Math.round(Number(v));
                const over = used > self.ENVELOPE;
                const card = document.querySelector(`.powerofyes-card-capital`);
                if (card) card.classList.toggle(`powerofyes-card-capital-over`, over);
                return self._money(used) + ` / ` + self._money(self.ENVELOPE);
            };
            uiManager.bind(`capitalDisplay`, `domainState.capital`, capitalFmt);
            uiManager.bind(`budgetDisplay`, `domainState.capital`, capitalFmt);

            // Covenant pill: reflects headroom discipline chosen in R3.
            uiManager.bind(`covenantDisplay`, `domainState.covenantBreach`, (breach) => {
                const pill = document.getElementById(`covenantDisplay`);
                if (pill) pill.classList.toggle(`powerofyes-covenant-breach`, !!breach);
                return window.mySimulation.t(breach ? `covenant_breach` : `covenant_ok`);
            });

            // Decisiveness slider readout (R1).
            const dec = document.getElementById(`decisivenessInput`);
            const decReadout = document.getElementById(`decisivenessReadout`);
            if (dec && decReadout) {
                decReadout.textContent = dec.value;
                dec.addEventListener(`input`, function() { decReadout.textContent = dec.value; });
            }

            // Covenant slider readout (R3).
            const cov = document.getElementById(`covenantInput`);
            const covReadout = document.getElementById(`covenantReadout`);
            if (cov && covReadout) {
                covReadout.textContent = cov.value;
                cov.addEventListener(`input`, function() { covReadout.textContent = cov.value; });
            }

            // Live allocation total (R2).
            const allocIds = [`omniInput`, `loyaltyInput`, `discountInput`, `quickInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total);
                if (allocReadout) allocReadout.textContent = total;
                const bar = document.querySelector(`.powerofyes-alloc-readout`);
                if (bar) bar.style.color = (total > self.ENVELOPE) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

