        getChartData(state) {
            const ds = state.domainState;
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const startLabel = t(`chart_start`);
            const labels = ds.clarityHistory.map((_, i) => (i === 0 ? startLabel : `R` + i));
            return {
                yesChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.clarityHistory },
                        { data: ds.positionHistory },
                        { data: ds.mandateHistory }
                    ]
                }
            };
        }

        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const clarity = Math.round(ds.clarity);
            const position = Math.round(ds.position);
            const mandate = Math.round(ds.mandate);
            return Math.max(0, Math.min(100, Math.round(clarity * 0.34 + position * 0.33 + mandate * 0.33)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || ``;   // already localized via perf_* keys in getPerformanceSummary
            const met = !!s.met;
            const badge = met
                ? `<span class="powerofyes-cm-badge powerofyes-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="powerofyes-cm-badge powerofyes-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.overCap) failBadge += ` <span class="powerofyes-cm-badge powerofyes-cm-no">` + T(`cm_overcap`) + `</span>`;
            if (!s.diagnosed) failBadge += ` <span class="powerofyes-cm-badge powerofyes-cm-no">` + T(`cm_nodiag`) + `</span>`;
            if (!s.focusedPair) failBadge += ` <span class="powerofyes-cm-badge powerofyes-cm-no">` + T(`cm_spread`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="powerofyes-cm-metric"><span class="powerofyes-cm-mv">` + Math.round(s.clarity || 0) + `</span><span class="powerofyes-cm-ml">` + T(`cm_m_clarity`) + `</span></div>`
                + `<div class="powerofyes-cm-metric"><span class="powerofyes-cm-mv">` + Math.round(s.position || 0) + `</span><span class="powerofyes-cm-ml">` + T(`cm_m_position`) + `</span></div>`
                + `<div class="powerofyes-cm-metric"><span class="powerofyes-cm-mv">` + Math.round(s.mandate || 0) + `</span><span class="powerofyes-cm-ml">` + T(`cm_m_mandate`) + `</span></div>`
                + `<div class="powerofyes-cm-metric"><span class="powerofyes-cm-mv">` + Math.round(s.capital || 0) + `</span><span class="powerofyes-cm-ml">` + T(`cm_m_capital`) + `</span></div>`;
            return ``
                + `<div class="powerofyes-completion">`
                +   `<div class="powerofyes-cm-head">`
                +     `<div class="powerofyes-cm-score">` + score + `<span class="powerofyes-cm-score-max">/100</span></div>`
                +     `<div class="powerofyes-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="powerofyes-cm-metrics">` + metrics + `</div>`
                +   `<div class="powerofyes-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="powerofyes-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const clarity = Math.round(ds.clarity);
            const position = Math.round(ds.position);
            const mandate = Math.round(ds.mandate);

            const composite = this._composite(ds);
            const committed = ds.diagnosed && ds.focusedPair && ds.realOption && ds.declinedClean;

            let performance = window.mySimulation.t(`perf_maybe`);
            if (composite >= 80 && committed && !ds.overCap) performance = window.mySimulation.t(`perf_powerofyes`);
            else if (composite >= 68 && ds.focusedPair) performance = window.mySimulation.t(`perf_committed`);
            else if (composite >= 52) performance = window.mySimulation.t(`perf_partial`);
            else if (ds.overCap) performance = window.mySimulation.t(`perf_overcommitted`);

            const insights = [];
            if (committed && composite >= 80) insights.push(window.mySimulation.t(`insight_yes`));
            if (!ds.diagnosed) insights.push(window.mySimulation.t(`insight_nodiagnosis`));
            if (!ds.focusedPair) insights.push(window.mySimulation.t(`insight_spread`));
            if (!ds.realOption) insights.push(window.mySimulation.t(`insight_nogates`));
            if (!ds.declinedClean) insights.push(window.mySimulation.t(`insight_nodecline`));
            if (mandate < 50) insights.push(window.mySimulation.t(`insight_lowmandate`));
            if (ds.overCap) insights.push(window.mySimulation.t(`insight_overcap`));

            return {
                clarity: clarity,
                position: position,
                mandate: mandate,
                capital: Math.round(ds.capital),
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                committed: committed,
                met: (composite >= 80 && committed && !ds.overCap),
                diagnosed: ds.diagnosed,
                focusedPair: ds.focusedPair,
                realOption: ds.realOption,
                declinedClean: ds.declinedClean,
                overCap: ds.overCap,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overCap) return window.mySimulation.t(`hint_overcap`);
            if (state.currentPeriod >= 2 && !ds.diagnosed) return window.mySimulation.t(`hint_diagnose`);
            if (state.currentPeriod >= 2 && !ds.focusedPair) return window.mySimulation.t(`hint_focus`);
            if (state.currentPeriod >= 3 && !ds.realOption) return window.mySimulation.t(`hint_gates`);
            if (state.currentPeriod >= 3 && ds.mandate < 45) return window.mySimulation.t(`hint_mandate`);
            if (ds.clarity >= 70 && ds.position >= 60 && ds.mandate >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

